def minSessions(tasks: list[int], sessionTime: int) -> int:
    n = len(tasks)
    dp = [(float('inf'), float('inf'))] * (1 << n)
    dp[0] = (1, 0)
    for mask in range(1 << n):
        sessions, rem = dp[mask]
        if sessions == float('inf'): continue
        for i in range(n):
            if not (mask & (1 << i)):
                nxt = mask | (1 << i)
                if rem + tasks[i] <= sessionTime:
                    cand = (sessions, rem + tasks[i])
                else:
                    cand = (sessions + 1, tasks[i])
                if cand < dp[nxt]:
                    dp[nxt] = cand
    return dp[(1 << n) - 1][0]

